def choose_move(observation):
    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def is_num(x):
        return isinstance(x, (int, float))

    def as_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [v[0], v[1]]
        return None

    def first_pair_from_keys(d, keys):
        for k in keys:
            if k in d:
                p = as_pair(d.get(k))
                if p is not None:
                    return p
        return None

    def find_self_pos(obs):
        p = first_pair_from_keys(obs, ("agent_pos", "self_pos", "position", "pos", "loc", "location", "me"))
        if p is not None:
            return p
        for k in ("agent", "self", "player"):
            v = obs.get(k)
            if isinstance(v, dict):
                p = first_pair_from_keys(v, ("pos", "position", "location", "loc", "xy"))
                if p is not None:
                    return p
        return [0, 0]

    def extract_points(obj):
        pts = []
        if obj is None:
            return pts
