            for v in obj.values():
                pts.extend(extract_points(v))
            return pts
        if isinstance(obj, (list, tuple)):
            if len(obj) >= 2 and is_num(obj[0]) and is_num(obj[1]):
                pts.append([obj[0], obj[1]])
            else:
                for v in obj:
                    pts.extend(extract_points(v))
        return pts

    def get_grid(obs):
        g = obs.get("grid")
        if g is None:
            g = obs.get("map")
        return g

    def grid_dims(grid):
        if isinstance(grid, list) and grid:
            h = len(grid)
            w = len(grid[0]) if isinstance(grid[0], list) else 0
            return w, h
        return None

    def cell(grid, x, y):
        if not isinstance(grid, list) or y < 0 or y >= len(grid):
            return None
        row = grid[y]
        if not isinstance(row, list) or x < 0 or x >= len(row):
            return None
        return row[x]

    def walkable(grid, x, y):
        c = cell(grid, x, y)
        if c is None:
            return True
        if c in (0, ".", " ", True):
            return True
        if c in (1, "#", "X", "x", "W", "w", "wall", "blocked"):
            return False
        return True

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(pos, pts):
        best = None
        best_d = 10**9
        for p in pts:
            d = manhattan(pos, p)
            if d < best_d:
                best_d = d
                best = p
        return best, best_d

