        enemies.extend(extract_points(v))

    control = []
    for k in ("territory", "frontier", "capture_points", "unclaimed", "bases"):
        control.extend(extract_points(obs.get(k)))

    own_territory = []
    for k in ("owned", "my_territory", "territory_owned", "home"):
        own_territory.extend(extract_points(obs.get(k)))

    target = None
    mode = "neutral"

    if resources:
        target, _ = nearest([x, y], resources)
        mode = "resource"
    elif control:
        target, _ = nearest([x, y], control)
        mode = "territory"
    elif enemies:
        target, _ = nearest([x, y], enemies)
        mode = "pursuit"

