    best_score = -10**18

    flee_weight = 8 if mode == "pursuit" else 3
    target_weight = 6 if mode == "resource" else (4 if mode == "territory" else 2)
    center_weight = 1

    cx = (dims[0] - 1) / 2 if dims else 0
    cy = (dims[1] - 1) / 2 if dims else 0

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = x + dx, y + dy
            if dims and not walkable(grid, nx, ny):
