            score = 0

            if target is not None:
                d0 = manhattan([x, y], target)
                d1 = manhattan([nx, ny], target)
                score += target_weight * (d0 - d1)

            if enemies:
                near_e = nearest([nx, ny], enemies)[1]
                score += flee_weight * near_e
                score -= max(0, 4 - near_e) * (10 if mode == "pursuit" else 6)

            if resources and mode != "pursuit":
                score += 2 if [nx, ny] in resources else 0

            if own_territory and mode == "territory":
                score -= 1 if [nx, ny] in own_territory else 0

            score -= center_weight * (abs(nx - cx) + abs(ny - cy)) * 0.05

            if dx == 0 and dy == 0:
                score -= 0.5

            if score > best_score:
                best_score = score
                best_move = [dx, dy]

    if best_move == [0, 0]:
        if target is not None:
            best_move = [clamp(target[0] - x), clamp(target[1] - y)]
        else:
            best_move = [1, 0] if (x + y) % 2 == 0 else [0, 1]

    return [int(best_move[0]), int(best_move[1])]

